insert into public.services (id, company_id, category_id, title_ar, title_en, description_ar, description_en, photos, position) values
  ('s1', 'c1', 0, 'بناء الفلل السكنية', 'Villa construction', 'تنفيذ الفلل من الأساسات حتى التشطيب، مع جدول زمني ومهندس موقع مخصص.', 'Villas built from foundations to finishing, with a set schedule and a dedicated site engineer.', array['1504307651254-35680f356dfd','1541888946425-d81bb19240f5','1600585154340-be6161a56a0c']::text[], 0),
  ('s2', 'c1', 0, 'مراجعة التصاميم الإنشائية', 'Structural design review', 'مراجعة المخططات الإنشائية قبل التنفيذ وتقديم تقرير بالملاحظات.', 'Review of structural drawings before construction, with a written report.', array['1503387762-592deb58ef4e','1581092160562-40aa08e78837']::text[], 1),
  ('s3', 'c2', 4, 'تصميم المجالس', 'Majlis interior design', 'تصميم مجالس الرجال والنساء: المخطط، الإضاءة، الجلسات، والستائر.', 'Majlis design for men and women: layout, lighting, seating and curtains.', array['1615874959474-d609969a20ed','1600210492486-724fe5c67fb0','1618221195710-dd6b41faaea6']::text[], 2),
  ('s4', 'c2', 4, 'تجهيز داخلي متكامل', 'Full home interior fit-out', 'تصميم وتنفيذ داخلي للمنزل بالكامل مع لوحة مواد واعتماد قبل التنفيذ.', 'Whole-home interior design and fit-out, with a materials board you approve first.', array['1600607687939-ce8a6c25118c','1617104678098-de229db51175','1586023492125-27b2c045efd7']::text[], 3),
  ('s5', 'c3', 2, 'تحديث لوحات الكهرباء', 'Electrical panel upgrade', 'استبدال اللوحات القديمة وتوزيع الأحمال وفحص التمديدات.', 'Replacing old panels, load balancing and wiring inspection.', array['1621905251189-08b45d6a269e','1621905252507-b35492cc74b4']::text[], 4),
  ('s7', 'c4', 9, 'تصميم وتركيب المطابخ', 'Kitchen design & installation', 'زيارة قياس، تصميم ثلاثي الأبعاد، تصنيع محلي، وتركيب خلال ٣–٥ أسابيع.', 'Measurement visit, 3D design, local manufacturing and installation in 3–5 weeks.', array['1484154218962-a197022b5858','1588854337236-6889d631faa8','1600566753190-17f0baa2a6c3']::text[], 5),
  ('s9', 'c5', 8, 'تصميم وتنفيذ الحدائق', 'Garden design & build', 'تصميم الحديقة، الزراعة، الممرات، والري بالتنقيط.', 'Garden design, planting, pathways and drip irrigation.', array['1558904541-efa843a96f01','1564013799919-ab600027ffc6','1416879595882-3373a0480b5b']::text[], 6),
  ('s11', 'c6', 6, 'تركيب كاميرات المراقبة', 'CCTV installation', 'كاميرات داخلية وخارجية مع مشاهدة مباشرة من الهاتف.', 'Indoor and outdoor cameras with live view on your phone.', array['1557597774-9d273605dfa9']::text[], 7),
  ('s12', 'c7', 1, 'تركيب المكيفات', 'AC installation', 'تركيب المكيفات المنفصلة مع التمديدات والتصريف.', 'Split AC installation including piping and drainage.', array['1545259741-2ea3ebf61fa3']::text[], 8),
  ('s13', 'c7', 1, 'صيانة المكيفات', 'AC maintenance', 'تنظيف، فحص الغاز، وصيانة دورية قبل الصيف.', 'Cleaning, refrigerant check and seasonal servicing before summer.', array['1545259741-2ea3ebf61fa3']::text[], 9),
  ('s17', 'c10', 6, 'مراقبة الفلل', 'Villa CCTV', 'نظام مراقبة متكامل للفلل مع تسجيل ٣٠ يومًا.', 'Complete villa surveillance with 30-day recording.', array['1557597774-9d273605dfa9']::text[], 10),
  ('s18', 'c10', 7, 'أنظمة إنذار الحريق', 'Fire alarm systems', 'تركيب أنظمة الإنذار والإطفاء وفق متطلبات الدفاع المدني.', 'Alarm and suppression systems installed to Civil Defence requirements.', array['1607472586893-edb57bdc0e39']::text[], 11),
  ('sg0-0-0', 'g0-0', 0, 'بناء الفلل', 'Villa construction', 'بناء الفلل من الريادة للمقاولات. نبدأ بزيارة للموقع ثم نرسل لك عرض سعر واضح.', 'Villa construction by Al Riyada Contracting. We start with a site visit, then send you a clear quotation.', array['1504307651254-35680f356dfd','1541888946425-d81bb19240f5']::text[], 12),
  ('sg0-0-1', 'g0-0', 0, 'ملاحق ومجالس خارجية', 'Annexes & outdoor majlis', 'ملاحق ومجالس خارجية من الريادة للمقاولات. نبدأ بزيارة للموقع ثم نرسل لك عرض سعر واضح.', 'Annexes & outdoor majlis by Al Riyada Contracting. We start with a site visit, then send you a clear quotation.', array['1541888946425-d81bb19240f5','1600585154340-be6161a56a0c']::text[], 13),
